const SOURCES = INVENTORY_SOURCES.filter((s) => [SOURCE].includes(s.key));

export const SCOTT_ELLIOT_1896_EVIDENCE =
  "The Story of Atlantis, by W. Scott-Elliot, with a preface by A. P. Sinnett (London: Theosophical Publishing Society, 1896), first edition; public domain (published 1896; Scott-Elliot died in 1930, Sinnett in 1921). Taken from Project Gutenberg #21796, a transcription of a later printing, and compared word by word with the archive.org OCRs of three copies of 1896 (University of California, Los Angeles, storyofatlantisg00scot; Digital Library of India, in.ernet.dli.2015.204900 and dli.ministry.23349) and of the revised edition of 1909 (in.ernet.dli.2015.38206); where at least three witnesses outvote the transcription their reading is taken. Two readings were taken by the vote ('colonized' for 'colonial', and the 1896 misprint 'goverment') and two places corrected by hand ('him self', 'were-filled'), read on the UCLA page images (pp. vii, 43, 61); the 1896 misprints that every 1896 copy shares are kept. Punctuation is not voted. All are listed in scripts/texts/atlantis-authors.py. Italic and small capitals are not marked.";

function englishLayer(section: ScottElliotSection): CorpusLayer {
  const where = section.id === "preface" ? "the Preface" : `the archive's section ${section.id}`;
  return {
    key: "eng-1896",
    layer: "primary_text",
    sourceKey: SOURCE,
    content: section.text,
    language: "English",
    licence: "public_domain",
    evidence: `${SCOTT_ELLIOT_1896_EVIDENCE} (${where}, pp. ${section.firstPage}–${section.lastPage})`,
  };
}

