function sectionPassage(section: ScottElliotSection): CorpusPassage {
  const meta = SECTIONS[section.id];
  const key = `${BOOK}.${section.id}`;
  const where =
    section.id === "preface"
      ? "the Preface by A. P. Sinnett"
      : `the archive's section ${section.id}${section.heading ? `, at the side-heading '${section.heading}'` : ""}`;
  return {
    key,
    parentKey: BOOK,
    divisionKind: "section",
    label: meta.label,
    reference: `The Story of Atlantis (London, 1896), ${where}, pp. ${section.firstPage}–${section.lastPage}`,
    sourceKey: SOURCE,
    summary: meta.summary,
    notes: meta.notes,
    verificationStatus: "unverified",
    layers: [englishLayer(section)],
    themes: meta.themes.map(([themeKey, note]) => ({ themeKey, note })),
    images: imagesFor(SCOTT_ELLIOT_IMAGES, key),
  };
}

const MAPS_NOTE = `The four maps, as titled on them: ${SCOTT_ELLIOT_MAPS.map((m) => `No. ${m.number}, '${m.title}' ('${m.name}'; ${m.seen.replace(/\.$/, "")})`).join("; ")}. The maps are Scott-Elliot's own of 1896; the book's claim that they copy maps among occult records is its claim.`;

